import Link from "next/link";
import { useState } from "react";
import { Plus, Search, Cpu, Radio, Activity } from "lucide-react";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Badge } from "@/components/ui/badge";
import { Led} from"@/components/ui/led";


const mockSmartMeters = [
  {
    id: "1",
    smartMeterId: "SM-001",
    name: "North Hub",
    location: "Sector A",
    status: "Active",
    sensors: 12,
    converters: 4,

    fx: true,
    tx: true,
    link: false,
    pwr: true,
    act: true,
    fdx: true,
  },

  {
    id: "2",
    smartMeterId: "SM-002",
    name: "East Hub",
    location: "Sector B",
    status: "Active",
    sensors: 8,
    converters: 2,

    fx: true,
    tx: true,
    link: true,
    pwr: true,
    act: true,
    fdx: true,
  },

  {
    id: "3",
    smartMeterId: "SM-003",
    name: "West Hub",
    location: "Sector C",
    status: "Inactive",
    sensors: 5,
    converters: 1,

    fx: false,
    tx: false,
    link: false,
    pwr: true,
    act: false,
    fdx: false,
  },
];



export default function SmartMeterPage() {
  const [searchTerm, setSearchTerm] = useState("");

  const filteredMeters = mockSmartMeters.filter(
    (meter) =>
      meter.name.toLowerCase().includes(searchTerm.toLowerCase()) ||
      meter.smartMeterId.toLowerCase().includes(searchTerm.toLowerCase())
  );

  const totalSensors = mockSmartMeters.reduce(
    (sum, meter) => sum + meter.sensors,
    0
  );

  const totalConverters = mockSmartMeters.reduce(
    (sum, meter) => sum + meter.converters,
    0
  );

  

  return (
    <div className="p-4 md:p-6 lg:p-8">
      <div className="mx-auto max-w-7xl">

        {/* Header */}
        <div className="mb-6 flex flex-col gap-4 sm:flex-row sm:items-center sm:justify-between">
          <div>
            <h1 className="text-2xl font-bold text-white md:text-3xl">
              Smart Meter Management
            </h1>
            <p className="mt-1 text-sm text-gray-400">
              Manage and monitor smart meter hubs
            </p>
          </div>

          <Link href="/smartmeter/add">
            <Button className="gap-2 bg-[#8B0000] hover:bg-[#6B0000]">
              <Plus className="h-4 w-4" />
              Add Smart Meter
            </Button>
          </Link>
        </div>

        {/* Stats */}
        <div className="mb-6 grid gap-4 sm:grid-cols-2 xl:grid-cols-4">

          <div className="rounded-lg border border-[#333] bg-[#222] p-4">
            <div className="flex items-center gap-2">
              <Cpu className="h-5 w-5 text-blue-400" />
              <span className="text-sm text-gray-400">
                Smart Meters
              </span>
            </div>
            <p className="mt-2 text-3xl font-bold text-white">
              {mockSmartMeters.length}
            </p>
          </div>

          <div className="rounded-lg border border-[#333] bg-[#222] p-4">
            <div className="flex items-center gap-2">
              <Activity className="h-5 w-5 text-green-400" />
              <span className="text-sm text-gray-400">
                Active
              </span>
            </div>
            <p className="mt-2 text-3xl font-bold text-green-400">
              {
                mockSmartMeters.filter(
                  (m) => m.status === "Active"
                ).length
              }
            </p>
          </div>

          <div className="rounded-lg border border-[#333] bg-[#222] p-4">
            <div className="flex items-center gap-2">
              <Radio className="h-5 w-5 text-blue-400" />
              <span className="text-sm text-gray-400">
                Sensors
              </span>
            </div>
            <p className="mt-2 text-3xl font-bold text-blue-400">
              {totalSensors}
            </p>
          </div>

          <div className="rounded-lg border border-[#333] bg-[#222] p-4">
            <div className="flex items-center gap-2">
              <Cpu className="h-5 w-5 text-yellow-400" />
              <span className="text-sm text-gray-400">
                Converters
              </span>
            </div>
            <p className="mt-2 text-3xl font-bold text-yellow-400">
              {totalConverters}
            </p>
          </div>
        </div>

        {/* Search */}
        <div className="mb-6">
          <div className="relative max-w-sm">
            <Search className="absolute left-3 top-1/2 h-4 w-4 -translate-y-1/2 text-gray-500" />
            <Input
              placeholder="Search smart meters..."
              value={searchTerm}
              onChange={(e) => setSearchTerm(e.target.value)}
              className="border-[#333] bg-[#222] pl-10 text-white placeholder:text-gray-500"
            />
          </div>
        </div>

        <div className="mb-6 rounded-lg border border-[#333] bg-[#222] p-4">
  <h3 className="mb-3 font-medium text-white">
    Converter Status Legend
  </h3>

  <div className="grid gap-3 md:grid-cols-3">
    <div>
      <span className="font-medium text-green-400">
        FX
      </span>
      <p className="text-xs text-gray-400">
        Fiber optic signal detected
      </p>
    </div>

    <div>
      <span className="font-medium text-green-400">
        TX
      </span>
      <p className="text-xs text-gray-400">
        Data transmission active
      </p>
    </div>

    <div>
      <span className="font-medium text-green-400">
        LINK
      </span>
      <p className="text-xs text-gray-400">
        Network link established
      </p>
    </div>

    <div>
      <span className="font-medium text-green-400">
        PWR
      </span>
      <p className="text-xs text-gray-400">
        Device power available
      </p>
    </div>

    <div>
      <span className="font-medium text-green-400">
        ACT
      </span>
      <p className="text-xs text-gray-400">
        Network activity detected
      </p>
    </div>

    <div>
      <span className="font-medium text-green-400">
        FDX
      </span>
      <p className="text-xs text-gray-400">
        Full duplex communication
      </p>
    </div>
  </div>
</div>

        
        {/* Cards */}
       <div className="grid gap-5 lg:grid-cols-2">
  {filteredMeters.map((meter) => {
    const leds = [
      meter.fx,
      meter.tx,
      meter.link,
      meter.pwr,
      meter.act,
      meter.fdx,
    ];

    const health = Math.round(
      (leds.filter(Boolean).length / leds.length) * 100
    );

    const faults = [];

    if (!meter.fx) faults.push("Fiber Signal Missing");
    if (!meter.tx) faults.push("No Data Transmission");
    if (!meter.link) faults.push("Network Link Failure");
    if (!meter.pwr) faults.push("Power Failure");
    if (!meter.act) faults.push("No Network Activity");
    if (!meter.fdx) faults.push("Half Duplex Mode");

    return (
      <div
        key={meter.id}
        className="
          rounded-xl
          border border-[#333]
          bg-gradient-to-b
          from-[#232323]
          to-[#181818]
          p-5
          shadow-2xl
          transition-all
          duration-300
          hover:border-[#555]
          hover:shadow-green-500/10
        "
      >
        {/* Header */}
        <div className="mb-4 flex items-center justify-between border-b border-[#333] pb-3">
          <div>
            <p className="text-[10px] tracking-[0.3em] text-gray-500">
              SMART METER
            </p>

            <h3 className="mt-1 text-lg font-bold text-white">
              {meter.smartMeterId}
            </h3>

            <p className="text-sm text-gray-400">
              {meter.name}
            </p>
          </div>

          <div className="flex items-center gap-2">
            <div
              className={`h-3 w-3 rounded-full ${
                meter.status === "Active"
                  ? "bg-green-400 shadow-[0_0_15px_#4ade80]"
                  : "bg-red-500 shadow-[0_0_15px_#ef4444]"
              }`}
            />

            <span
              className={`text-xs font-semibold ${
                meter.status === "Active"
                  ? "text-green-400"
                  : "text-red-400"
              }`}
            >
              {meter.status.toUpperCase()}
            </span>
          </div>
        </div>

        {/* Location */}
        <div className="mb-4 text-sm text-gray-400">
          📍 {meter.location}
        </div>

        {/* Stats */}
        <div className="mb-4 grid grid-cols-2 gap-3">
          <div className="rounded-lg bg-black/30 p-3 text-center">
            <p className="text-xs text-gray-400">
              Devices
            </p>
            <p className="text-xl font-bold text-blue-400">
              {meter.sensors}
            </p>
          </div>

          <div className="rounded-lg bg-black/30 p-3 text-center">
            <p className="text-xs text-gray-400">
              Converters
            </p>
            <p className="text-xl font-bold text-yellow-400">
              {meter.converters}
            </p>
          </div>
        </div>

        {/* Health */}
        <div className="mb-5">
          <div className="mb-2 flex justify-between">
            <span className="text-xs text-gray-400">
              NETWORK HEALTH
            </span>

            <span className="text-xs font-bold text-white">
              {health}%
            </span>
          </div>

          <div className="h-2 overflow-hidden rounded-full bg-[#111]">
            <div
              className={`h-full rounded-full transition-all duration-700 ${
                health > 80
                  ? "bg-green-500"
                  : health > 50
                  ? "bg-yellow-500"
                  : "bg-red-500"
              }`}
              style={{
                width: `${health}%`,
              }}
            />
          </div>
        </div>

        {/* LEDs */}
        <div className="mb-5 flex justify-between rounded-lg border border-[#333] bg-black/20 p-4">
          <Led active={meter.fx} label="FX" />
          <Led active={meter.tx} label="TX" />
          <Led active={meter.link} label="LINK" />
          <Led active={meter.pwr} label="PWR" />
          <Led active={meter.act} label="ACT" />
          <Led active={meter.fdx} label="FDX" />
        </div>

        {/* Fault Panel */}
        {faults.length > 0 ? (
          <div className="rounded-lg border border-red-500/30 bg-red-500/10 p-3">
            <p className="mb-2 text-xs font-bold text-red-400">
              ACTIVE FAULTS
            </p>

            {faults.map((fault) => (
              <div
                key={fault}
                className="text-xs text-red-300"
              >
                • {fault}
              </div>
            ))}
          </div>
        ) : (
          <div className="rounded-lg border border-green-500/30 bg-green-500/10 p-3">
            <p className="text-xs font-bold text-green-400">
              ALL SYSTEMS OPERATIONAL
            </p>
          </div>
        )}
      </div>
    );
  })}
</div>

      </div>
    </div>
  );
}